import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {chromium} from 'playwright-core';
const out=process.env.TRADING_EVIDENCE_DIR;const browser=await chromium.connectOverCDP(process.env.TRADING_CDP_URL);const page=browser.contexts()[0].pages().find(p=>p.url().includes('/trading-proof'));page.setDefaultTimeout(12000);
const panel=()=>page.locator('[data-panel-id]:visible').filter({has:page.locator('[data-workspace-section="chart"]')}).first();const d=()=>panel().getByRole('region',{name:'Discover markets',exact:true});
const top=()=>page.evaluate(()=>{document.activeElement?.blur();document.querySelectorAll('*').forEach(e=>{if(e.scrollTop)e.scrollTop=0;});});
const open=async(tab,label)=>{await d().getByRole('button',{name:tab,exact:true}).click();await d().getByRole('button',{name:label,exact:true}).click();};
async function ready(){await page.waitForFunction(()=>typeof document.getElementById('trading-open')?.onclick==='function');if(!await page.locator('[data-workspace-host]').count())await page.locator('#trading-open').click();await page.waitForFunction(()=>!!window.tradingFixture);}
try {
 await page.bringToFront();await page.setViewportSize({width:1414,height:1100});await page.emulateMedia({reducedMotion:'reduce'});const cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});await page.reload();await ready();if(!await panel().getByRole('button',{name:'Copy KSTL coin address'}).count())await open('New coins','Open KSTL coin');
 await page.evaluate(()=>window.tradingFixture.state('A','ready'));const amount=panel().locator('[data-panel-amount]');await amount.fill('123.45');await page.waitForFunction(()=>[...document.querySelectorAll('[data-panel-id="A"] button')].some(b=>b.textContent==='Buy KSTL'&&!b.disabled));
 await page.evaluate(()=>window.fullwidthAmount=document.querySelector('[data-panel-id="A"] [data-panel-amount]'));
 await page.getByRole('button',{name:'Edit layout',exact:true}).click();await panel().getByRole('button',{name:'Move Trade earlier',exact:true}).click();assert.equal(await page.evaluate(()=>window.fullwidthAmount===document.querySelector('[data-panel-id="A"] [data-panel-amount]')),true);assert.equal(await amount.inputValue(),'123.45');const g=await panel().locator('[data-workspace-section]').evaluateAll(es=>Object.fromEntries(es.map(e=>[e.dataset.workspaceSection,e.getBoundingClientRect().toJSON()])));assert.ok(g.chart.x<g.trade.x&&g.trade.x<g.activity.x);assert.equal(g.details.x,g.chart.x);assert.equal(g.details.right,g.activity.right);await page.getByRole('button',{name:'Cancel',exact:true}).click();
 const height=panel().getByRole('separator',{name:/height/});const before=Number(await height.getAttribute('aria-valuenow'));const hb=await height.boundingBox();await page.mouse.move(hb.x+100,hb.y+hb.height/2);await page.mouse.down();await page.mouse.move(hb.x+100,hb.y+hb.height/2+50,{steps:5});await page.keyboard.press('Escape');await page.mouse.up();await page.waitForTimeout(100);assert.equal(Number(await height.getAttribute('aria-valuenow')),before);
 await height.focus();await page.keyboard.press('ArrowDown');const saved=Number(await height.getAttribute('aria-valuenow'));await page.waitForTimeout(300);await page.reload();await ready();await page.waitForFunction(()=>[...document.querySelectorAll('[data-panel-id="A"] button')].some(b=>b.textContent==='Buy KSTL'&&!b.disabled));assert.equal(await panel().locator('[data-panel-amount]').inputValue(),'123.45');assert.equal(Number(await panel().getByRole('separator',{name:/height/}).getAttribute('aria-valuenow')),saved);await page.evaluate(()=>{const s=window.tradingFixture.store,l=s.getSnapshot().layout;s.setLayout({...l,terminal:{...l.terminal,height:460,widths:[50,25,25]}});});
 await page.waitForFunction(()=>[...document.querySelectorAll('[data-panel-id="A"] button')].some(b=>b.textContent==='Buy KSTL'&&!b.disabled));await top();for(const theme of ['light','dark']){await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await page.screenshot({path:out+`/final-coin-${theme}.png`});}
 await open('Presales','Open NOVA presale');await panel().getByRole('textbox',{name:'Commit amount',exact:true}).fill('100');await page.waitForFunction(()=>[...document.querySelectorAll('[data-presale-submit]')].some(b=>b.textContent==='Commit'&&!b.disabled));await panel().locator('[data-tradingview-plot][data-ready]').waitFor();
 assert.ok(await panel().locator('[data-tradingview-plot][data-ready] canvas').count()>0);await top();for(const theme of ['light','dark']){await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await page.screenshot({path:out+`/final-presale-${theme}.png`});}
 const heightHandle=panel().getByRole('separator',{name:/height/});await heightHandle.focus();await page.keyboard.press('End');await page.waitForTimeout(100);const chartHeight=await panel().locator('[data-tradingview-plot][data-ready]').evaluate(e=>e.getBoundingClientRect().height);assert.ok(chartHeight>700);await heightHandle.focus();await page.keyboard.press('Home');
 await page.emulateMedia({contrast:'more'});await top();await page.screenshot({path:out+'/increased-contrast.png'});await page.emulateMedia({contrast:'no-preference'});await cdp.send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-transparency',value:'reduce'}]});await page.screenshot({path:out+'/reduced-transparency.png'});
 writeFileSync(out+'/final-interactions.json',JSON.stringify({reorderingRetainsDom:true,cancelRestoresHeight:true,reloadPersistsHeightAndDraft:true,latestPresalePath:path,fundingHeightAtMaximum:chartHeight},null,2));console.log('PASS final captures, reordered full-width discovery, stable draft DOM, pointer cancellation, reload persistence and funding chart expansion');
}finally{await browser.close();}
